/* 3.5 overlay player: a single video surface with touch-sized controls. */
.dshoof-player{position:relative;isolation:isolate;aspect-ratio:16/9;min-width:0;background:#000;color:#fff;outline-offset:3px}
.dshoof-player .screen{position:absolute;inset:0;width:100%;height:100%;aspect-ratio:auto;background:#000}
.dshoof-player .screen>video,.dshoof-player .screen>iframe{position:absolute;inset:0;width:100%;height:100%;object-fit:contain}
.dshoof-player .player-brand{position:absolute;inset:0 0 auto;z-index:6;display:flex;flex-direction:column;align-items:flex-end;gap:3px;padding:14px 18px 35px;background:linear-gradient(#0009,transparent);pointer-events:none;font-size:12px;text-shadow:0 1px 3px #000}
.dshoof-player .player-brand strong{font-size:13px}.dshoof-player .player-brand span{color:#ddd;font-size:11px}
.dshoof-player .dshoof-controls{position:absolute;inset:auto 0 0;z-index:8;display:flex;flex-direction:column;gap:0;flex-wrap:nowrap;background:linear-gradient(transparent,#000b);padding:25px max(14px,env(safe-area-inset-right)) max(8px,env(safe-area-inset-bottom)) max(14px,env(safe-area-inset-left));border:0;direction:ltr}
.dshoof-player .player-chrome{opacity:1;visibility:visible;transition:opacity .2s,visibility .2s}
.dshoof-player.controls-hidden .player-chrome{opacity:0;visibility:hidden;pointer-events:none}.dshoof-player.controls-hidden{cursor:none}
.dshoof-player .player-timeline{display:flex;width:100%;height:24px;margin:0;padding:0;border:0}
.dshoof-player .player-timeline input{height:24px;width:100%;min-height:24px;min-width:0;cursor:pointer;accent-color:#ff8068;background:transparent;box-shadow:none;margin:0;padding:0}
.dshoof-player .player-control-row{width:100%;display:flex;align-items:center;justify-content:space-between;gap:6px;min-width:0}
.dshoof-player .toolbar,.dshoof-player .player-right-controls{display:flex;align-items:center;gap:2px;flex-wrap:nowrap;margin:0;padding:0;border:0;min-width:0}
.dshoof-player .dshoof-controls button{display:inline-flex;align-items:center;justify-content:center;gap:5px;flex-shrink:0;width:44px;height:44px;min-width:44px;min-height:44px;padding:10px;background:transparent;color:#fff;border:0;border-radius:6px;box-shadow:none;cursor:pointer}
.dshoof-player .dshoof-controls button:hover{background:#ffffff20}.dshoof-player button:focus-visible,.dshoof-player input:focus-visible,.dshoof-player select:focus-visible{outline:2px solid #ffaf9d;outline-offset:1px}
