.dshoof-player .dshoof-controls svg{width:23px;height:23px;flex-shrink:0;stroke:currentColor}
.dshoof-player #go-live{width:auto;padding-inline:9px;direction:rtl}.dshoof-player #go-live>span{position:static;clip:auto;width:auto;height:auto;overflow:visible;font-size:12px;font-weight:700}.dshoof-player #go-live svg{width:17px;height:17px;color:#ff8068}
