import {test} from 'node:test';import assert from 'node:assert/strict';import vm from 'node:vm';import {readFile} from 'node:fs/promises';
const source=await readFile(new URL('./public/app.js',import.meta.url),'utf8');
function player({seekable=true,sync=194,currentTime=100}={}){const loads=[],v={seekable:{length:seekable?1:0,start:()=>20,end:()=>200},currentTime,playbackRate:1.25,play:async()=>{v.played=true;}},hls={liveSyncPosition:sync,config:{liveMaxLatencyDurationCount:Infinity,maxLiveSyncPlaybackRate:1},startLoad:p=>loads.push(p)},follow={checked:true},context={state:{selection:{kind:'url'}},hls,paused:true,running:true,$:id=>id==='video'?v:follow,notice(){},watch(){context.restarted=true;}};vm.createContext(context);vm.runInContext(source.slice(source.indexOf('function liveTarget('),source.indexOf('function watch(){')),context);return {context,v,hls,loads,follow};}
test('live button seeks the current live point, resumes a paused loader and exits follower sync',()=>{const f=player();f.context.goLive();assert.equal(f.v.currentTime,194);assert.equal(f.v.played,true);assert.equal(f.context.paused,false);assert.equal(f.v.playbackRate,1);assert.equal(f.follow.checked,false);assert.deepEqual(f.loads,[194]);assert.equal(f.hls.config.liveMaxLatencyDurationCount,8);assert.equal(f.hls.config.maxLiveSyncPlaybackRate,1.02);});
test('live button works before seekable ranges exist and native HLS has a bounded fallback',()=>{const f=player({seekable:false});f.context.goLive();assert.equal(f.v.currentTime,194);const n=player({sync:null});n.context.hls=null;n.context.goLive();assert.equal(n.v.currentTime,197);const c=player({seekable:false,sync:NaN});c.context.goLive();assert.deepEqual(c.loads,[-1]);});
test('live point never seeks beyond the advertised media and cold start restarts playback',()=>{const f=player({sync:250});f.context.goLive();assert.equal(f.v.currentTime,199.8);f.context.running=false;f.context.goLive();assert.equal(f.context.restarted,true);});

test('rewind stays behind live until the viewer presses live again',()=>{const f=player();vm.runInContext('const v=$("video");'+source.slice(source.indexOf('function seekPlayer('),source.indexOf("$('player-seek').onchange")),f.context);f.context.seekPlayer(80);assert.equal(f.v.currentTime,80);assert.equal(f.hls.config.liveMaxLatencyDurationCount,Infinity);assert.equal(f.hls.config.maxLiveSyncPlaybackRate,1);f.context.goLive();assert.equal(f.v.currentTime,194);assert.equal(f.hls.config.liveMaxLatencyDurationCount,8);});
